Rules.InvariantScript:
If(_cmpAlAll || _cmpAlExpanded = 0, Blank(), _cmpAlExpanded)
// ZERO IS THE INTERNAL SENTINEL, BLANK IS THE PUBLIC CONTRACT. Callers get
// a blank when nothing is open, which is what a caller expects; the
// component never stores a blank, which is what keeps the variable typed.

Set(_cmpAlExpanded, 0);
Set(_cmpAlItemKey, 0);
Set(_cmpAlActionKey, 0);
Set(_cmpAlActionType, "");
Set(_cmpAlAll, false)
// ZERO, NOT Blank(). These two literals are the ONLY place either variable
// is assigned from outside galAlRows, so they are where Power Fx gets the
// type from. Every other Set sits inside the gallery template, and that
// template is driven by Items, which reads _cmpAlExpanded, so the type
// would depend on a formula that depends on the variable being typed.
// Blank() carries no type, the circle never closes, and the component
// fails to compile with "No type found for variable".
//
// NOTHING ELSE TO CLEAR. The component holds two numbers and no
// collections, so Reset is genuinely just this.

Set(_cmpAlAll, !_cmpAlAll);
Set(_cmpAlExpanded, 0)
// COLLAPSING ALL CLEARS THE SINGLE SELECTION TOO, so the list
// does not snap back to whichever group happened to be open
// before expand-all was pressed. Leaving it set is the kind of
// state that only shows up as a bug report months later.

With(
    {
        gi: ForAll(
            Sort(cmpAccordionList.Groups, GroupOrder) As x,
            {
                GroupKey: x.GroupKey,
                Pos: CountRows(
                    Filter(cmpAccordionList.Groups, GroupOrder <= x.GroupOrder)
                ),
                Cnt: If(
                    _cmpAlAll || x.GroupKey = _cmpAlExpanded,
                    CountRows(
                        Filter(cmpAccordionList.Items, GroupKey = x.GroupKey)
                    ),
                    0
                ),
                Before: Coalesce(
                    Sum(
                        ForAll(
                            Filter(
                                cmpAccordionList.Groups,
                                GroupOrder < x.GroupOrder
                            ) As y,
                            If(
                                _cmpAlAll || y.GroupKey = _cmpAlExpanded,
                                CountRows(
                                    Filter(
                                        cmpAccordionList.Items,
                                        GroupKey = y.GroupKey
                                    )
                                ),
                                0
                            )
                        ),
                        Value
                    ),
                    0
                )
            }
        )
    },
    ForAll(
        Sequence(
            CountRows(cmpAccordionList.Groups) + Coalesce(Sum(gi, Cnt), 0)
        ) As s,
        With(
            { o: Last(Sort(Filter(gi, Pos + Before <= s.Value), Pos + Before)) },
            With(
                {
                    g: LookUp(
                        cmpAccordionList.Groups,
                        GroupKey = o.GroupKey
                    ),
                    ci: s.Value - (o.Pos + o.Before)
                },
                With(
                    {
                        isChild: ci > 0,
                        c: Last(
                            FirstN(
                                Sort(
                                    Filter(
                                        cmpAccordionList.Items,
                                        GroupKey = o.GroupKey
                                    ),
                                    ItemOrder
                                ),
                                Max(ci, 1)
                            )
                        )
                    },
                    {
                        RowType: If(isChild, "item", "group"),
                        SortOrder: g.GroupOrder,
                        GroupKey: g.GroupKey,
                        RowKey: If(isChild, c.ItemKey, g.GroupKey),
                        Marker: If(isChild, c.Marker, g.Marker),
                        Title: If(isChild, c.Title, g.Title),
                        Subtitle: If(isChild, c.Subtitle, g.Subtitle),
                        Tag: If(isChild, c.Tag, g.Tag),
                        Tone: If(isChild, c.Tone, g.Tone),
                        IsExpanded: _cmpAlAll || g.GroupKey = _cmpAlExpanded,
                        Locked: If(isChild, c.Locked, g.Locked),
                        CanMoveUp: If(
                            isChild,
                            CountRows(
                                Filter(
                                    cmpAccordionList.Items,
                                    GroupKey = g.GroupKey,
                                    ItemOrder < c.ItemOrder
                                )
                            ) > 0,
                            CountRows(
                                Filter(
                                    cmpAccordionList.Groups,
                                    GroupOrder < g.GroupOrder
                                )
                            ) > 0
                        ),
                        CanMoveDown: If(
                            isChild,
                            CountRows(
                                Filter(
                                    cmpAccordionList.Items,
                                    GroupKey = g.GroupKey,
                                    ItemOrder > c.ItemOrder
                                )
                            ) > 0,
                            CountRows(
                                Filter(
                                    cmpAccordionList.Groups,
                                    GroupOrder > g.GroupOrder
                                )
                            ) > 0
                        ),
                        ChildCount: CountRows(
                            Filter(
                                cmpAccordionList.Items,
                                GroupKey = g.GroupKey
                            )
                        ),
                        Meta: If(
                            isChild,
                            c.Meta,
                            If(
                                IsBlank(g.Meta),
                                With(
                                    {
                                        n: CountRows(
                                            Filter(
                                                cmpAccordionList.Items,
                                                GroupKey = g.GroupKey
                                            )
                                        )
                                    },
                                    n & If(n = 1, " item", " items")
                                ),
                                g.Meta
                            )
                        )
                    }
                )
            )
        )
    )
)
// NO STRING COLUMN NAMES ANYWHERE IN THIS FORMULA, which is the whole
// reason it looks like this. Ungroup, SortByColumns, ShowColumns and
// AddColumns all take a column NAME, and whether that name is written
// bare or quoted depends on the Formula-level column names app
// setting. The same formula is therefore valid in one app and
// rejected in the next, which is fatal for a component meant to be
// pasted into somebody else's environment. Sequence, Sort, Filter and
// a record literal all take formulas, and formulas do not care.
//
// gi IS THE PREFIX SUM, and building it as a ForAll over a record
// literal is what makes ANY set of groups expandable rather than one
// at a time. Pos is the group's position, Cnt is how many child rows
// it currently contributes, and Before is how many child rows every
// expanded group ahead of it contributes. Pos + Before is therefore
// the row index of that group's own header, and the arithmetic holds
// whether one group is open or all of them are.
//
// AddColumns would have expressed gi in a quarter of the space. It is
// banned here for the reason above, and a ForAll over a record literal
// is the portable equivalent.
//
// o IS THE OWNING GROUP: the last group whose header index has not
// passed this row yet. ci is the distance from that header, so zero
// means the header itself and anything above it is that child.
//
// NO COLLECTION AND NO REBUILD STEP. The flat list is a pure formula
// over the two input tables, so a host that swaps Groups or Items
// sees the change immediately. A component has no OnVisible, so
// anything built with ClearCollect needs an action property the caller
// must remember to invoke, and a caller who forgets gets an empty
// control and no error to explain it.
//
// NO NESTED GALLERY EITHER, which is the usual way this shape gets
// built and the reason it usually goes wrong. One flat gallery means
// one scroll container, working keyboard order, and no flexible height
// measurement to fight.
//
// THE COST IS REAL. gi is rebuilt per row rather than once, so this is
// quadratic in the group count. It is comfortable into the low
// hundreds of groups and is the wrong control above that; a list that
// big wants server side paging, not an accordion.
//
// THE EDGE FLAGS ARE COMPUTED HERE, not in each button. CanMoveUp and
// CanMoveDown ask whether any sibling sits before or after this row IN
// ITS OWN SCOPE: other groups for a group, other children of the same
// group for a child. Doing it once means the disabled state cannot
// disagree between the group and item templates.
//
// ORDER VALUES NEED NOT BE CONTIGUOUS. The test is whether a smaller
// or larger order exists, never whether it is exactly one away, so
// orders of 10, 20, 30 reorder correctly.
//
// ONE RECORD SHAPE, branched per field. Groups and Items carry the
// SAME COLUMN NAMES precisely so this projection stays one literal;
// building two and hoping they match is how column sets drift apart,
// and a table whose rows disagree on columns widens silently.

Parent.Width - 2
- If(
      Coalesce(cmpAccordionList.Config.AllowReorder, true)
          || Coalesce(cmpAccordionList.Config.AllowEdit, true)
          || Coalesce(cmpAccordionList.Config.AllowDelete, true),
      172,
      0
  )
// THE OVERLAY STOPS SHORT OF THE ACTION CLUSTER. A
// full width transparent button declared after the
// action buttons would sit on top of them and swallow
// every click, and the failure looks like the icons
// simply do nothing.

Set(
    _cmpAlExpanded,
    If(
        _cmpAlAll,
        ThisItem.GroupKey,
        ThisItem.IsExpanded,
        0,
        ThisItem.GroupKey
    )
);
Set(_cmpAlAll, false);
cmpAccordionList.OnSelectGroup()
// TAPPING A ROW WHILE EVERYTHING IS OPEN drops back to
// single-expand on the row that was tapped, rather than
// collapsing it inside a still-expanded list. Collapsing
// one group out of many would need an expanded SET rather
// than one key, and a set means a collection, which is the
// one thing this component does not have.
//
// _cmpAlAll IS READ BEFORE IT IS WRITTEN. Set is not
// synchronous for downstream formula evaluation, so the
// branch that depends on the old value has to be the
// earlier statement.
// THE EVENT FIRES AFTER THE STATE CHANGES, so a host reading
// ExpandedGroupKey inside OnSelectGroup sees the new value
// rather than the one it just replaced.
